                        return True
        return False
    if not exists_feasible():
        # Instance not sufficiently challenging or no feasible pair; reject
        return (False, None)

    # Construct the final answer string with necessary and sufficient conditions
    ans = []
    ans.append("### The final answer is: ")
    ans.append("Let k_n = (n+r)/2 and k_m = (m+s)/2. Define A = (n+r−m−s)/2, B = (n−r−m+s)/2 + 1, and K = ")
    ans.append("\\frac{\\binom{n}{k_n}}{\\lambda\\, \\binom{m}{k_m}} with \\lambda = %s." % (('{:.6f}'.format(lam)).rstrip('0').rstrip('.')))
    ans.append(" The inequality x_{r,n}(p) > \\lambda(1-p)\\, y_{s,m}(p) holds for every p\\in[%s,1) if and only if all of the following are satisfied:" % (('{:.2f}'.format(p_min)).rstrip('0').rstrip('.')))
    ans.append(" (i) Parity and feasibility: n\\equiv r \\ (\\mathrm{mod}\\ 2), m\\equiv s \\ (\\mathrm{mod}\\ 2), n\\ge r, m\\ge s, and %d\\le n\\le %d, %d\\le m\\le %d." % (n_min, n_max, m_min, m_max))
    ans.append(" (ii) Endpoint condition: B \\le 0, i.e., n−m \\le r−s−2.")
    ans.append(" (iii) Endpoint minima exceed 1 as follows:")
    ans.append(" • If B<0: K\\, p_{\\min}^{A} (1−p_{\\min})^{B} > 1.")
    ans.append(" • If B=0: then, writing K = \\frac{\\binom{n}{k_n}}{\\lambda\\, \\binom{m}{k_m}}, one of the following must hold:")
    ans.append("   – If A>0: K\\, p_{\\min}^{A} > 1.")
    ans.append("   – If A=0: K > 1.")
    ans.append("   – If A<0: K \\ge 1.")
    ans.append(" Here p_{\\min} = %s. These conditions are necessary and sufficient because x_{r,n}(p) = \\binom{n}{k_n} p^{k_n} (1-p)^{n-k_n}, y_{s,m}(p) = \\binom{m}{k_m} p^{k_m} (1-p)^{m-k_m}, and the function f(p) = K p^{A} (1-p)^{B} has concave log on (0,1), so its minimum over [p_{\\min},1) occurs at an endpoint." % (('{:.2f}'.format(p_min)).rstrip('0').rstrip('.')))
    answer = ''.join(ans)
    return (True, answer)


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
                assignment = generator(rng)
                valid, answer = verifier(assignment)
                if valid:
                    question = LANGUAGE_WRAPPER.format(**assignment)
                    return {
                        "assignment": assignment,
                        "question": question,
                        "answer": answer,
                        "attempts": attempts,
                        "elapsed_seconds": time.time() - start,
                    }
            raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

